package com.archos.mediacenter.video.utils;

import android.app.Application;
import android.content.Context;
import androidx.preference.PreferenceManager;
import com.archos.mediacenter.video.utils.backup.*;
import com.archos.mediaprovider.video.VideoOpenHelper;
import java.io.*;
import java.util.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(application=Application.class,sdk=28) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public class MediaMatchInventoryTest {
    private Context app;
    @Before public void setup(){app=RuntimeEnvironment.getApplication();app.deleteDatabase("media.db");PreferenceManager.getDefaultSharedPreferences(app).edit().clear().putString("oauth_token","AUTH_CANARY").commit();}
    private void seed(){try(VideoOpenHelper helper=new VideoOpenHelper(app)){var db=helper.getWritableDatabase();db.execSQL("INSERT INTO files(_id,remote_id,media_type,_data,ArchosMediaScraper_type,ArchosMediaScraper_id,bookmark) VALUES(10,10,3,'file:///PRIVATE_ONE.mkv',11,100,4444),(11,11,3,'file:///PRIVATE_TWO.mkv',11,200,5555),(12,12,3,'file:///episode.mkv',12,300,-2),(13,13,3,'file:///unmatched.mkv',0,0,0),(14,14,3,'putio:///ACCOUNT_CANARY/file',11,400,0)");db.execSQL("INSERT INTO MOVIE(_id,video_id,m_online_id,Nova_pinned,name_movie,plot_movie) VALUES(100,10,123,9,'One','Original facts'),(200,11,456,8,'Two','Other facts'),(400,14,987,0,'Remote','Private')");db.execSQL("INSERT INTO SHOW(_id,s_online_id,name_show) VALUES(20,789,'Show')");db.execSQL("INSERT INTO EPISODE(_id,video_id,show_episode,season_episode,number_episode,e_online_id,name_episode) VALUES(300,12,20,0,2,999,'Episode')");}}
    @Test public void absentReceivingStoreRemainsAbsentAndDoesNotAllocateOriginPreferences()throws Exception{var before=PreferenceManager.getDefaultSharedPreferences(app).getAll();var inventory=MediaMatchInventory.capture(app);assertTrue(inventory.owners.isEmpty());assertTrue(inventory.targets().isEmpty());assertFalse(VideoOpenHelper.getDatabaseFile(app).exists());assertEquals(before,PreferenceManager.getDefaultSharedPreferences(app).getAll());assertEquals(64,inventory.signature.length());}
    @Test public void actualMovieEpisodeAndUnmatchedOwnersRemainDistinctAndPutioIsExcluded()throws Exception{seed();var before=PreferenceManager.getDefaultSharedPreferences(app).getAll();var inventory=MediaMatchInventory.capture(app);assertEquals(Set.of(10L,11L,12L,13L),inventory.owners.keySet());assertEquals(3,inventory.targets().size());assertEquals(100,inventory.owners.get(10L).localId);assertEquals("tmdb:movie:123",inventory.owners.get(10L).match.identity);assertEquals("tmdb:tv:789:0:2",inventory.owners.get(12L).match.identity);assertNull(inventory.owners.get(13L).match);assertEquals(64,inventory.owners.get(10L).guard.length());inventory.validatePhysical(new PortablePhysicalReferences(app,LogicalBackupCatalog.capture(app,()->false).physical));assertEquals(before,PreferenceManager.getDefaultSharedPreferences(app).getAll());}
    @Test public void signatureTracksIdentificationAndPathButNotUnselectedWatchPinOrScrapedFacts()throws Exception{seed();String original=MediaMatchInventory.capture(app).signature;try(VideoOpenHelper helper=new VideoOpenHelper(app)){var db=helper.getWritableDatabase();db.execSQL("UPDATE files SET bookmark=7777,Archos_lastTimePlayed=200 WHERE _id=10");db.execSQL("UPDATE MOVIE SET Nova_pinned=5,plot_movie='Updated facts' WHERE _id=100");}assertEquals(original,MediaMatchInventory.capture(app).signature);try(VideoOpenHelper helper=new VideoOpenHelper(app)){helper.getWritableDatabase().execSQL("UPDATE MOVIE SET m_online_id=888 WHERE _id=100");}String changed=MediaMatchInventory.capture(app).signature;assertNotEquals(original,changed);try(VideoOpenHelper helper=new VideoOpenHelper(app)){helper.getWritableDatabase().execSQL("UPDATE files SET _data='file:///moved.mkv' WHERE _id=10");}assertNotEquals(changed,MediaMatchInventory.capture(app).signature);}
    @Test public void pointerCannotBorrowAnotherFilesMetadataEvenWhenNativeViewStillJoinsItsOwnMovie()throws Exception{seed();try(VideoOpenHelper helper=new VideoOpenHelper(app)){var db=helper.getWritableDatabase();db.execSQL("UPDATE files SET ArchosMediaScraper_type=0 WHERE _id=10");db.execSQL("UPDATE files SET ArchosMediaScraper_id=200 WHERE _id=10");db.execSQL("UPDATE files SET ArchosMediaScraper_type=11 WHERE _id=10");}try{MediaMatchInventory.capture(app);fail();}catch(IOException expected){}try(VideoOpenHelper helper=new VideoOpenHelper(app)){try{PortableMediaMatches.read(helper.getReadableDatabase());fail();}catch(IOException expected){}}try(VideoOpenHelper helper=new VideoOpenHelper(app);var rows=helper.getReadableDatabase().rawQuery("SELECT video_id,m_online_id,Nova_pinned FROM MOVIE WHERE _id=200",null)){assertTrue(rows.moveToFirst());assertEquals(11,rows.getLong(0));assertEquals(456,rows.getLong(1));assertEquals(8,rows.getLong(2));}}
    @Test public void changedPhysicalPreviewIsRejectedReadOnlyWithoutMovingMetadata()throws Exception{seed();var physical=new PortablePhysicalReferences(app,LogicalBackupCatalog.capture(app,()->false).physical);try(VideoOpenHelper helper=new VideoOpenHelper(app)){helper.getWritableDatabase().execSQL("UPDATE files SET _data='file:///changed.mkv' WHERE _id=10");}try{MediaMatchInventory.capture(app).validatePhysical(physical);fail();}catch(IOException expected){}assertEquals("AUTH_CANARY",PreferenceManager.getDefaultSharedPreferences(app).getString("oauth_token",null));}
}
